    // The entry an action came from (its kind, and its step when the entry has one).
    fun entry(a: JSONObject?): Entry? {
        if (a == null) return null
        val k = a.optString("k")
        return ENTRIES.firstOrNull { it.k == k && (it.what == null || it.what == a.optString("what")) }
    }
    fun available(e: Entry, caps: JSONObject?, platform: String): String? {
        if (e.needs.isEmpty() || caps?.optBoolean(e.needs, true) != false) return null
        return when {
            platform == "linux" && e.needs == "screenoff" -> "Not on Linux"
            platform == "linux" && e.needs == "windows" -> "Not on Wayland"
            platform == "mac" && e.needs == "dnd" -> "macOS has no switch for apps"
            else -> "Not on this computer"
        }
    }

    private fun icon(name: String, d: String, filled: Boolean): ImageVector = ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply {
        addPath(pathData = PathParser().parsePathString(d).toNodes(), fill = if (filled) SolidColor(Color.Black) else null, stroke = SolidColor(Color.Black),
            strokeLineWidth = 1.8f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round)
    }.build()
